const dummy = new THREE.Object3D();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();
  const cycle = 6;
  const phase = t % cycle;

  controls.update();

  heroGroup.rotation.y = Math.sin(t * 0.2) * 0.05;

  if (phase < 2) {
    const chargeProgress = phase / 2;
    const pulse = 1 + Math.sin(t * 15) * 0.15;
    const scale = chargeProgress * 1.2 * pulse;
    chargeOrb.scale.set(scale, scale, scale);
    chargeOrb.material.emissiveIntensity = 1.5 + Math.sin(t * 20) * 0.5;

    beamCore.scale.set(0, 0, 0);
    beamMid.scale.set(0, 0, 0);
    beamOuter.scale.set(0, 0, 0);

    beamLight.intensity = THREE.MathUtils.lerp(0, 8, chargeProgress);

    leftLowerGroup.rotation.x = -1.2 + Math.sin(t * 10) * 0.05;
    rightLowerGroup.rotation.x = -1.2 + Math.sin(t * 10) * 0.05;

  } else if (phase < 2.3) {
    const fireProgress = (phase - 2) / 0.3;
    const ease = 1 - Math.pow(1 - fireProgress, 3);

    const beamLength = 40 * ease;

    chargeOrb.scale.set(1.2 * (1 - ease * 0.5), 1.2 * (1 - ease * 0.5), 1.2 * (1 - ease * 0.5));

    beamCore.scale.set(0.5, beamLength, 0.5);
    beamMid.scale.set(1.0, beamLength, 1.0);
    beamOuter.scale.set(1.6, beamLength, 1.6);

    beamCore.position.z = beamLength / 2;
    beamMid.position.z = beamLength / 2;
    beamOuter.position.z = beamLength / 2;

    beamLight.intensity = 8 + Math.sin(t * 30) * 2;
    beamLight.position.z = beamLength * 0.8;

  } else {
    const sustain = (phase - 2.3) / (cycle - 2.3);
    const pulse = 1 + Math.sin(t * 25) * 0.08;
    const beamLength = 40;

    chargeOrb.scale.set(0.6 * pulse, 0.6 * pulse, 0.6 * pulse);

    beamCore.scale.set(0.5 * pulse, beamLength, 0.5 * pulse);
    beamMid.scale.set(1.0 * pulse, beamLength, 1.0 * pulse);
    beamOuter.scale.set(1.6 * pulse, beamLength, 1.6 * pulse);

    beamCore.position.z = beamLength / 2;
    beamMid.position.z = beamLength / 2;
    beamOuter.position.z = beamLength / 2;

    beamLight.intensity = 6 + Math.sin(t * 20) * 3;
    beamLight.position.z = Math.sin(t * 5) * 2;

    for (let i = 0; i < particleCount; i++) {
      const data = particleData[i];
      const zPos = ((t * data.speed + data.offset) % beamLength) - 2;
      const radius = data.radius * (1 - Math.abs(zPos) / beamLength);

      dummy.position.set(
        Math.cos(t * 3 + data.angle) * radius * 0.3,
        Math.sin(t * 2 + data.angle) * radius * 0.3,
        zPos
      );
      dummy.scale.setScalar(1 + Math.sin(t * 10 + i) * 0.3);
      dummy.updateMatrix();
      particles.setMatrixAt(i, dummy.matrix);
    }
    particles.instanceMatrix.needsUpdate = true;

    leftLowerGroup.rotation.x = -1.2 + Math.sin(t * 15) * 0.08;
    rightLowerGroup.rotation.x = -1.2 + Math.sin(t * 15) * 0.08;
  }

  beamMid.material.emissiveIntensity = 1.5 + Math.sin(t * 30) * 0.8;
  beamCore.material.opacity = 0.7 + Math.sin(t * 40) * 0.2;

  rimLight.intensity = 0.4 + Math.sin(t * 1.3) * 0.1;

  renderer.render(scene, camera);
}

